(function(){'use strict';
const shell=document.querySelector('.zpA');if(!shell)return;
const menu=shell.querySelector('.menu'),sidebar=shell.querySelector('.sidebar'),dialog=shell.querySelector('.zpA-command');
function closeMenu(){if(menu)menu.setAttribute('aria-expanded','false');if(sidebar)sidebar.classList.remove('open');}
if(menu)menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));sidebar.classList.toggle('open',open);});
function command(){if(!dialog)return;if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');dialog.querySelector('input').focus();}
shell.querySelector('[data-zp-command-open]')?.addEventListener('click',command);
shell.querySelector('[data-zp-command-close]')?.addEventListener('click',()=>dialog.close());
const commandSearch=shell.querySelector('#zpA-command-search');if(commandSearch)commandSearch.addEventListener('input',()=>{const text=commandSearch.value.trim().toLocaleLowerCase('pl');let n=0;dialog.querySelectorAll('nav a').forEach(a=>{a.hidden=!a.textContent.toLocaleLowerCase('pl').includes(text);if(!a.hidden)n++;});dialog.querySelector('[data-zp-command-empty]').hidden=n>0;});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();command();}});
const root=document.getElementById('zpt2-admin'),configNode=document.getElementById('zpA-translator-config');if(!root||!configNode)return;
let config;try{config=JSON.parse(configNode.textContent);}catch(e){return;}
const labels={new:'Nowa treść',changed:'Zmieniona PL',published:'Gotowe EN',legacy:'Gotowe EN',queued:'W kolejce',translating:'Tłumaczenie',repairing:'Naprawa fragmentu',checking:'Kontrola wyniku',deferred:'Czeka na limit znaków',attention:'Wymaga sprawdzenia',unknown:'Nieznany wynik'};
const search=root.querySelector('#zpt2-search'),tbody=root.querySelector('tbody'),form=root.querySelector('[data-zpt2-translate]'),all=root.querySelector('[data-zpt2-select-all]'),submit=root.querySelector('[data-zpt2-submit]');let filter='todo',timer=null,inflight=false,polls=0;
const ready=state=>state==='published'||state==='legacy';const eligible=state=>state==='new'||state==='changed';
const rows=()=>Array.from(tbody.querySelectorAll('[data-zpt2-row]'));const choices=()=>Array.from(tbody.querySelectorAll('input[name="ids[]"]'));
function applyFilter(){const term=search.value.trim().toLocaleLowerCase('pl');let visible=0;rows().forEach(row=>{const state=row.dataset.state;row.hidden=!(filter==='todo'?!ready(state):filter==='published'?ready(state):filter===state)||!row.textContent.toLocaleLowerCase('pl').includes(term);if(!row.hidden)visible++;});root.querySelector('[data-zpt2-empty]').hidden=visible>0;selection();}
function selection(){const checked=choices().filter(c=>c.checked);submit.disabled=checked.length<1||checked.length>10;root.querySelector('[data-zpt2-selection]').textContent=checked.length?'Wybrano treści: '+checked.length:'Wybierz treści do tłumaczenia';const hidden=checked.filter(c=>c.closest('tr').hidden).length;root.querySelector('[data-zpt2-selection-note]').textContent=hidden?'Wybór obejmuje '+hidden+' treści ukrytych przez filtr.':'Limit: 10 treści w jednym zadaniu.';const visible=choices().filter(c=>!c.disabled&&!c.closest('tr').hidden);all.checked=visible.length>0&&visible.every(c=>c.checked);all.indeterminate=visible.some(c=>c.checked)&&!all.checked;}
root.querySelectorAll('[data-zpt2-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.zpt2Filter;root.querySelectorAll('[data-zpt2-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});applyFilter();}));search.addEventListener('input',applyFilter);
tbody.addEventListener('change',event=>{if(event.target.matches('input[name="ids[]"]')){if(choices().filter(c=>c.checked).length>10){event.target.checked=false;root.querySelector('#zpt2-live').textContent='Możesz zaznaczyć maksymalnie 10 treści.';}selection();}});
all.addEventListener('change',()=>{const checked=all.checked;let count=choices().filter(c=>c.checked&&c.closest('tr').hidden).length;choices().forEach(c=>{if(c.disabled||c.closest('tr').hidden)return;c.checked=checked&&count<10;if(c.checked)count++;});selection();});
form.addEventListener('submit',event=>{const selected=choices().filter(c=>c.checked&&!c.disabled);if(selected.length<1||selected.length>10){event.preventDefault();root.querySelector('#zpt2-live').textContent='Wybierz od 1 do 10 nowych lub zmienionych treści.';}else{submit.disabled=true;submit.textContent='Zlecanie tłumaczenia…';}});
function safeUrl(path){if(typeof path!=='string'||!path.startsWith('/')||path.startsWith('//')||/[\x00-\x20\\]/.test(path))return null;try{const base=new URL(config.home_url),u=new URL(base.pathname.replace(/\/$/,'')+path,base);return u.origin===base.origin?u.href:null;}catch(e){return null;}}
function makeRow(data){const row=document.createElement('tr');row.dataset.zpt2Row=String(data.post_id);for(let n=0;n<5;n++)row.appendChild(document.createElement('td'));const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.name='ids[]';checkbox.value=String(data.post_id);row.children[0].appendChild(checkbox);const strong=document.createElement('strong'),small=document.createElement('small');row.children[1].append(strong,small);const badge=document.createElement('span');badge.className='zpt2-state tag';const error=document.createElement('small');error.className='zpt2-error';row.children[2].append(badge,error);row.children[3].className='zpt2-progress';row.children[4].className='zpA-row-links';tbody.appendChild(row);return row;}
function updateRow(row,data){const state=typeof data.state==='string'?data.state:'unknown';row.dataset.state=state;const check=row.querySelector('input');check.disabled=!eligible(state);if(check.disabled)check.checked=false;check.setAttribute('aria-label','Zaznacz: '+String(data.title||'Treść'));row.children[1].querySelector('strong').textContent=String(data.title||'Treść');row.children[1].querySelector('small').textContent=String(data.source||'');const badge=row.querySelector('.zpt2-state');badge.textContent=labels[state]||'Nieznany stan';badge.className='zpt2-state tag '+(ready(state)?'green':state==='new'?'blue':'amber');row.querySelector('.zpt2-error').textContent=typeof data.error==='string'?data.error:'';row.querySelector('.zpt2-progress').textContent=Number.isFinite(data.total)?String(data.done||0)+' / '+String(data.total):'—';const links=row.children[4];links.replaceChildren();[['source','PL'],['en','EN']].forEach(([key,label])=>{if(key==='en'&&!ready(state))return;const url=safeUrl(data[key]);if(!url)return;const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent=label+' ↗';a.setAttribute('aria-label',String(data.title||'Treść')+' — '+label);links.appendChild(a);});}
function money(micro){return typeof micro==='number'&&Number.isFinite(micro)&&micro>=0?(micro/1e6).toLocaleString('pl-PL',{minimumFractionDigits:3,maximumFractionDigits:3})+' USD':'Brak odczytu';}
function date(value){if(!value)return 'brak pomiaru';const t=typeof value==='number'?new Date(value*1000):new Date(value);return Number.isNaN(t.getTime())?'brak pomiaru':t.toLocaleString('pl-PL',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function update(data){if(!Array.isArray(data.rows))throw Error('invalid_status');const ids=new Set(),counts={todo:0,new:0,changed:0,published:0};let active=0;data.rows.forEach(item=>{if(!item||!Number.isSafeInteger(Number(item.post_id))||Number(item.post_id)<1)return;const id=String(item.post_id);ids.add(id);const existing=rows().find(r=>r.dataset.zpt2Row===id);updateRow(existing||makeRow(item),item);if(ready(item.state))counts.published++;else counts.todo++;if(item.state==='new'||item.state==='changed')counts[item.state]++;if(['queued','translating','repairing','checking','deferred'].includes(item.state))active++;});rows().forEach(row=>{if(!ids.has(row.dataset.zpt2Row))row.remove();});Object.entries(counts).forEach(([key,value])=>{root.querySelector('[data-zpt2-count="'+key+'"]').textContent=String(value);});root.querySelector('#zpt2-live').textContent=active?active+' treści w kolejce lub w trakcie pracy.':'Brak aktywnego zadania.';const scan=data.scan||{};root.querySelector('[data-zpt2-scan]').textContent=scan.state==='running'?'Skanowanie: '+String(scan.cursor||0)+' / '+String(scan.total||'—'):date(scan.completed_at||scan.at);root.querySelector('[data-zpt2-eta]').textContent=Number.isFinite(data.eta_seconds)?'Mediana ukończonego zadania: '+data.eta_seconds+' s.':'Czas realizacji pojawi się po pierwszych pomiarach.';['settled','reserved','limit'].forEach(key=>{root.querySelector('[data-zpt2-budget="'+key+'"]').textContent=money(data.budget?.[key]);});const b=data.budget;root.querySelector('[data-zpt2-budget-bar]').style.width=(b&&Number.isFinite(b.limit)&&b.limit>0?Math.max(0,Math.min(100,100*((b.settled||0)+(b.reserved||0))/b.limit)):0)+'%';applyFilter();return active>0||scan.state==='running';}
async function poll(manual){if(inflight)return;if(!manual&&(shell.dataset.live!=='1'||++polls>720))return;if(!manual&&document.visibilityState!=='visible'){timer=setTimeout(()=>poll(false),15000);return;}inflight=true;clearTimeout(timer);let delay=30000;const note=root.querySelector('[data-zpt2-poll-status]');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);try{const endpoint=new URL(config.ajax_url,location.href);if(endpoint.origin!==location.origin)throw Error('invalid_origin');endpoint.searchParams.set('action','zpt2_status');endpoint.searchParams.set('_ajax_nonce',config.status_nonce);const response=await fetch(endpoint.href,{credentials:'same-origin',cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('http_status');const json=await response.json();if(!json.success||!json.data)throw Error('invalid_status');delay=update(json.data)?5000:30000;note.textContent='Status odczytany: '+new Date().toLocaleTimeString('pl-PL')+'.';}catch(e){note.textContent='Nie udało się odczytać statusu. Zachowano ostatnie dane; użyj „Odśwież status”.';delay=30000;}finally{clearTimeout(timeout);inflight=false;if(shell.dataset.live==='1'&&polls<=720)timer=setTimeout(()=>poll(false),delay);}}
root.querySelector('[data-zpt2-refresh]').addEventListener('click',()=>poll(true));applyFilter();if(shell.dataset.live==='1')timer=setTimeout(()=>poll(false),5000);
})();
